func TestGeneratedInvalid(t *testing.T) {
	for _, c := range invalidCases {
		var ve *ieee20305.ValidationError
		if err := c.err(); !errors.As(err, &ve) {
			t.Errorf("%s: Validate = %v, want a ValidationError", c.name, err)
		}
	}
}

