func TestGeneratedScalars(t *testing.T) {
	for _, c := range scalarCases {
		if err := c.valid.Validate(); err != nil {
			t.Errorf("%s: valid value: %v", c.name, err)
		}
		for i, v := range c.invalid {
			if v.Validate() == nil {
				t.Errorf("%s: invalid value %d (%v) accepted", c.name, i, v)
			}
		}
	}
}

